// Normalizes Gmail Trigger output into clean fields for the AI.
// Works whether the trigger's 'Simplify' toggle is ON or OFF.
const MAX_BODY_CHARS = 4000; // caps token cost per email
const results = [];

const decode = (data) => {
  try {
    return Buffer.from(String(data).replace(/-/g, '+').replace(/_/g, '/'), 'base64').toString('utf8');
  } catch (e) {
    return '';
  }
};

const findTextPart = (p) => {
  if (!p) return null;
  if (p.mimeType === 'text/plain' && p.body && p.body.data) return p;
  if (Array.isArray(p.parts)) {
    for (const sub of p.parts) {
      const hit = findTextPart(sub);
      if (hit) return hit;
    }
  }
  return null;
};

for (const item of $input.all()) {
  const j = item.json || {};
  let from = '';
  let subject = '';
  let body = '';

  // Raw Gmail API shape (Simplify OFF)
  if (j.payload && Array.isArray(j.payload.headers)) {
    const header = (name) => (j.payload.headers.find((h) => String(h.name).toLowerCase() === name) || {}).value || '';
    from = header('from');
    subject = header('subject');
    const part = findTextPart(j.payload) || (j.payload.body && j.payload.body.data ? j.payload : null);
    if (part) body = decode(part.body.data);
  }

  // Simplified shape fallbacks (Simplify ON)
  if (!from) from = (j.from && j.from.text) ? j.from.text : (j.From || '');
  if (!subject) subject = j.subject || j.Subject || '';
  if (!body) body = j.text || j.textPlain || j.snippet || '';

  // Drop quoted reply history, collapse whitespace, cap length
  body = String(body)
    .split(/\r?\n(?:>|On .{5,80} wrote:)/)[0]
    .replace(/[\t ]+/g, ' ')
    .replace(/\n{3,}/g, '\n\n')
    .trim()
    .slice(0, MAX_BODY_CHARS);

  const emailMatch = String(from).match(/[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/);

  results.push({
    json: {
      messageId: j.id || '',
      threadId: j.threadId || '',
      fromRaw: String(from).trim(),
      fromEmail: emailMatch ? emailMatch[0].toLowerCase() : '',
      subject: String(subject).trim(),
      bodyText: body,
      snippet: j.snippet || '',
      receivedAt: j.internalDate ? new Date(Number(j.internalDate)).toISOString() : new Date().toISOString()
    }
  });
}

return results;

// Safely parses the AI JSON and maps each category to a Gmail label.
// ================= EDIT ME: paste your Gmail label IDs =================
// How to find them: see the 'Finding Gmail label IDs' sticky note.
const LABEL_MAP = {
  sales_lead: 'PASTE_SALES_LEAD_LABEL_ID',
  support: 'PASTE_SUPPORT_LABEL_ID',
  urgent: 'PASTE_URGENT_LABEL_ID',
  spam: 'PASTE_SPAM_LABEL_ID'
};
// =======================================================================
const ALLOWED = ['sales_lead', 'support', 'urgent', 'spam'];
const items = $input.all();
const results = [];

for (let i = 0; i < items.length; i++) {
  let src = {};
  try {
    src = $('Extract & Clean Email').itemMatching(i).json;
  } catch (e) {
    // keep empty, fall back to defaults below
  }

  const resp = items[i].json || {};
  const raw = resp.choices && resp.choices[0] && resp.choices[0].message ? String(resp.choices[0].message.content || '') : '';

  let ai = null;
  try {
    ai = JSON.parse(raw);
  } catch (e) {
    // Model wrapped JSON in prose or fences: grab the outermost object
    const match = raw.match(/\{[\s\S]*\}/);
    if (match) {
      try { ai = JSON.parse(match[0]); } catch (e2) { ai = null; }
    }
  }

  const parseFailed = !ai || typeof ai !== 'object';
  if (parseFailed) ai = {};

  let category = String(ai.category || '').toLowerCase().trim().replace(/[\s-]+/g, '_');
  if (!ALLOWED.includes(category)) category = 'support'; // safe default: a human reviews every draft anyway

  const draftSubject = String(ai.draft_subject || '').trim() || ('Re: ' + (src.subject || 'your email'));
  let draftBody = String(ai.draft_body || '').trim();
  if (!draftBody && category !== 'spam') {
    draftBody = 'Hello,\n\nThank you for your email. We have received it and will get back to you shortly.\n\nBest regards,';
  }

  results.push({
    json: {
      messageId: src.messageId || '',
      threadId: src.threadId || '',
      fromRaw: src.fromRaw || '',
      fromEmail: src.fromEmail || '',
      subject: src.subject || '',
      receivedAt: src.receivedAt || '',
      category: category,
      confidence: typeof ai.confidence === 'number' ? ai.confidence : 0,
      summary: String(ai.summary || src.snippet || '').slice(0, 300),
      urgencyReason: String(ai.urgency_reason || ''),
      draftSubject: draftSubject,
      draftBody: draftBody,
      labelId: LABEL_MAP[category] || '',
      isUrgent: category === 'urgent',
      parseFailed: parseFailed
    }
  });
}

return results;
